const express = require('express');
const crypto = require('crypto');
const app = express();

// In-memory feature flag store with atomic operations
class FeatureFlagStore {
  constructor() {
    this.flags = new Map();
    this.evaluationCache = new Map();
    this.pendingUpdates = new Map();
  }

  setFlag(name, config) {
    this.flags.set(name, { ...config, version: Date.now() });
    this.evaluationCache.delete(name);
  }

  getFlag(name) {
    return this.flags.get(name) || null;
  }

  getCachedEvaluation(name, contextHash) {
    const cache = this.evaluationCache.get(name);
    if (!cache) return null;
    if (cache.contextHash === contextHash && cache.version === this.flags.get(name)?.version) {
      return cache.result;
    }
    return null;
  }

  setCachedEvaluation(name, contextHash, result) {
    const flag = this.flags.get(name);
    if (flag) {
      this.evaluationCache.set(name, { contextHash, result, version: flag.version });
    }
  }
}

const store = new FeatureFlagStore();

// Role-based access control middleware
const ROLE_HIERARCHY = { admin: 3, manager: 2, user: 1, guest: 0 };

function requireRole(minRole) {
  return (req, res, next) => {
    const userRole = req.headers['x-user-role'] || 'guest';
    if ((ROLE_HIERARCHY[userRole] || 0) >= ROLE_HIERARCHY[minRole]) {
      req.userRole = userRole;
      next();
    } else {
      res.status(403).json({ error: 'Insufficient permissions' });
    }
  };
}

// Feature flag evaluation engine
class FlagEvaluator {
  constructor(store) {
    this.store = store;
    this.evaluationLock = new Map();
  }

  async evaluate(flagName, context) {
    const contextHash = crypto.createHash('sha256')
      .update(JSON.stringify(context))
      .digest('hex');

    const cached = this.store.getCachedEvaluation(flagName, contextHash);
    if (cached !== null) return cached;

    // Acquire evaluation lock to prevent duplicate computation
    if (this.evaluationLock.has(flagName)) {
      await this.evaluationLock.get(flagName);
      const rechecked = this.store.getCachedEvaluation(flagName, contextHash);
      if (rechecked !== null) return rechecked;
    }

    let resolve;
    const lockPromise = new Promise(r => { resolve = r; });
    this.evaluationLock.set(flagName, lockPromise);

    try {
      const result = await this._computeEvaluation(flagName, context);
      this.store.setCachedEvaluation(flagName, contextHash, result);
      return result;
    } finally {
      this.evaluationLock.delete(flagName);
      resolve();
    }
  }

  async _computeEvaluation(flagName, context) {
    const flag = this.store.getFlag(flagName);
    if (!flag) return { enabled: false, reason: 'flag_not_found' };

    if (!flag.enabled) return { enabled: false, reason: 'flag_disabled' };

    // Evaluate targeting rules
    if (flag.rules && flag.rules.length > 0) {
      for (const rule of flag.rules) {
        if (this._matchesRule(rule, context)) {
          return { enabled: rule.serve, reason: 'rule_match', ruleId: rule.id };
        }
      }
    }

    // Percentage rollout
    if (flag.rolloutPercentage !== undefined) {
      const hash = crypto.createHash('md5')
        .update(`${flagName}:${context.userId || 'anonymous'}`)
        .digest('hex');
      const bucket = parseInt(hash.substring(0, 8), 16) % 100;
      return { enabled: bucket < flag.rolloutPercentage, reason: 'rollout' };
    }

    return { enabled: flag.enabled, reason: 'default' };
  }

  _matchesRule(rule, context) {
    if (!rule.conditions) return false;
    return rule.conditions.every(cond => {
      const value = context[cond.attribute];
      switch (cond.operator) {
        case 'eq': return value === cond.value;
        case 'neq': return value !== cond.value;
        case 'in': return Array.isArray(cond.value) && cond.value.includes(value);
        case 'gt': return value > cond.value;
        default: return false;
      }
    });
  }
}

const evaluator = new FlagEvaluator(store);

// Admin endpoint to update flags
app.use(express.json());

app.put('/api/flags/:name', requireRole('admin'), async (req, res) => {
  const { name } = req.params;
  const { enabled, rules, rolloutPercentage, metadata } = req.body;

  // Stage the update
  store.pendingUpdates.set(name, {
    enabled,
    rules: rules || [],
    rolloutPercentage,
    metadata: metadata || {},
    updatedBy: req.headers['x-user-id'] || 'unknown'
  });

  // Simulate async validation (e.g., schema check, dependency resolution)
  await new Promise(resolve => setImmediate(resolve));

  // Commit the update from pending
  const pending = store.pendingUpdates.get(name);
  if (pending) {
    store.setFlag(name, pending);
    store.pendingUpdates.delete(name);
  }

  res.json({ success: true, flag: store.getFlag(name) });
});

// Evaluation endpoint
app.post('/api/flags/:name/evaluate', requireRole('user'), async (req, res) => {
  const { name } = req.params;
  const context = req.body.context || {};
  context.userRole = req.userRole;
  context.userId = req.headers['x-user-id'] || 'anonymous';

  const result = await evaluator.evaluate(name, context);
  res.json(result);
});

// Batch evaluation
app.post('/api/flags/evaluate-batch', requireRole('user'), async (req, res) => {
  const { flags, context } = req.body;
  if (!Array.isArray(flags)) {
    return res.status(400).json({ error: 'flags must be an array' });
  }

  const enrichedContext = {
    ...context,
    userRole: req.userRole,
    userId: req.headers['x-user-id'] || 'anonymous'
  };

  const results = {};
  await Promise.all(flags.map(async (flagName) => {
    results[flagName] = await evaluator.evaluate(flagName, enrichedContext);
  }));

  res.json(results);
});

// Health check with flag status
app.get('/api/health', (req, res) => {
  res.json({
    status: 'healthy',
    flagCount: store.flags.size,
    cacheSize: store.evaluationCache.size
  });
});

module.exports = app;
